import React from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../styles/AdminDashboard.css"; // Optional if you want custom admin styles

const AdminDashboard = () => {
  return (
    <>
      <Navbar />
      <div className="admin-dashboard-wrapper">
        <h1>Welcome, Admin 👑</h1>
        <p>This is your control panel.</p>

        <div className="admin-cards">
          <a href="/admin-users" className="admin-card">Manage Users</a>
          <a href="/admin-reports" className="admin-card">View Reports</a>
          <a href="/admin-flagged" className="admin-card">Flagged Listings</a>
        </div>
      </div>
      <Footer />
    </>
  );
};

export default AdminDashboard;
